/// Merge overlapping maintenance windows into a compact schedule.
///
/// Pinned windows are returned exactly as requested: they never merge with a
/// neighbour and never absorb regular windows. Regular windows merge among
/// themselves as before.
pub fn merge_windows(windows: &[Window]) -> Vec<Window> {
    let mut ordered: Vec<Window> = windows.iter().copied().filter(|w| !w.pinned).collect();
    ordered.sort_by_key(|w| (w.start, w.end));
    let mut merged: Vec<Window> = Vec::new();
    for w in ordered {
        match merged.last_mut() {
            Some(last) if last.overlaps(&w) => {
                last.end = last.end.max(w.end);
            }
            _ => merged.push(w),
        }
    }
    merged
}

